begin;create extension if not exists pgtap with schema extensions;set local search_path=public,extensions;select plan(28);
insert into auth.users(id,email)values('e1000000-0000-4000-8000-000000000001','dep-admin@test.local'),('e1000000-0000-4000-8000-000000000002','dep-manager@test.local'),('e1000000-0000-4000-8000-000000000003','dep-member@test.local'),('e1000000-0000-4000-8000-000000000004','dep-viewer@test.local'),('e1000000-0000-4000-8000-000000000005','dep-out@test.local');insert into profiles(id,email,full_name)select id,email,email from auth.users where id::text like'e1000000-%';
