select set_config('request.jwt.claim.sub','e1000000-0000-4000-8000-000000000002',true);select throws_ok($$select satisfy_project_dependency((select id from project_dependencies),' ','Notes')$$,'22023','Required dependency outcome information is missing.','Evidence required');select throws_ok($$select fail_project_dependency((select id from project_dependencies),' ')$$,'22023','Required dependency outcome information is missing.','Failure notes required');select lives_ok($$select satisfy_project_dependency((select id from project_dependencies),'Signed approval','Provider delivered')$$,'Manager satisfies');select ok((select satisfied_by='e1000000-0000-4000-8000-000000000002'and satisfied_at is not null from project_dependencies),'Terminal audit trusted');select throws_ok($$select update_project_dependency((select id from project_dependencies),'No','D','Internal','P','O','F','I','M','e4000000-0000-4000-8000-000000000002',current_date)$$,'42501','Dependency update is not permitted.','Terminal edit denied');select throws_ok($$select transition_project_dependency_active((select id from project_dependencies),'Identified')$$,'42501','Dependency transition is not permitted.','Reopen denied');select throws_ok($$delete from project_dependencies$$,'42501','permission denied for table project_dependencies','Direct delete denied');select * from finish();rollback;
